//! `market_price` parity against CPython.
//!
//! Fixtures are generated by `tests/gen_market_vectors.py` from
//! `kaggle_environments.envs.kaggriculture.kaggriculture` (1.32.7):
//!
//! * `data/market_price_vectors.csv` — `product_index,inventory,K.market_price(...)`
//!   for all 9 products over 4666 inventories each (every integer in 9000..=11000,
//!   a coarse sweep from -3000 up to 40000, and a few extremes).
//! * `data/market_raw_vectors.csv` — the *unrounded* price as raw IEEE-754 bits, so a
//!   1-ULP difference anywhere in `_shape` / the `amp` arithmetic is caught before
//!   rounding can hide it.

use kaggri_core::consts::{Product, MARKET_PARAMS};
use kaggri_core::sim::{market_price, raw_market_price};

fn rows(csv: &str) -> impl Iterator<Item = Vec<&str>> {
    csv.lines()
        .filter(|l| !l.trim_start().starts_with('#') && !l.trim().is_empty())
        .map(|l| l.trim().split(',').collect())
}

#[test]
fn market_price_matches_cpython_over_the_fixture_sweep() {
    let csv = include_str!("data/market_price_vectors.csv");
    let mut n = 0usize;
    for r in rows(csv) {
        let item = Product::from_idx(r[0].parse().unwrap()).unwrap();
        let inventory: i64 = r[1].parse().unwrap();
        let want: i64 = r[2].parse().unwrap();
        let got = market_price(item, inventory, &MARKET_PARAMS);
        assert_eq!(
            got,
            want,
            "market_price({}, {}) -> {} but CPython says {} (raw {:?})",
            item.as_str(),
            inventory,
            got,
            want,
            raw_market_price(MARKET_PARAMS.get(item), inventory)
        );
        n += 1;
    }
    assert!(n > 40_000, "fixture looks truncated: only {n} rows");
    println!("{n} market_price vectors matched CPython exactly");
}

#[test]
fn raw_price_is_bit_identical_to_cpython() {
    let csv = include_str!("data/market_raw_vectors.csv");
    let mut n = 0usize;
    for r in rows(csv) {
        let item = Product::from_idx(r[0].parse().unwrap()).unwrap();
        let inventory: i64 = r[1].parse().unwrap();
        let want_bits = u64::from_str_radix(r[2], 16).unwrap();
        let got = raw_market_price(MARKET_PARAMS.get(item), inventory);
        assert_eq!(
            got.to_bits(),
            want_bits,
            "raw_market_price({}, {}) = {} ({:016x}) but CPython gives {} ({:016x})",
            item.as_str(),
            inventory,
            got,
            got.to_bits(),
            f64::from_bits(want_bits),
            want_bits
        );
        n += 1;
    }
    assert!(n > 3_000, "fixture looks truncated: only {n} rows");
    println!("{n} raw (unrounded) prices matched CPython bit for bit");
}

/// The seven inventories in 9000..=11000 whose raw price is exactly `*.5`, i.e. every
/// case where banker's rounding is observable. All seven are CARROT.
#[test]
fn every_exact_half_case_rounds_to_even() {
    // (inventory, raw price, CPython round)
    let cases = [
        (9325i64, 157.5f64, 158i64),
        (9595, 66.5, 66),
        (9685, 59.5, 60),
        (9775, 52.5, 52),
        (9865, 45.5, 46),
        (9955, 38.5, 38),
        (10450, 10.5, 10),
    ];
    for (inv, raw, want) in cases {
        let got_raw = raw_market_price(MARKET_PARAMS.get(Product::Carrot), inv);
        assert_eq!(got_raw, raw, "raw price for CARROT @ {inv}");
        assert_eq!(
            market_price(Product::Carrot, inv, &MARKET_PARAMS),
            want,
            "CARROT @ {inv} must round half-to-even"
        );
        // Rust's own f64::round would be wrong for three of these.
        if want % 2 == 0 && raw.round() as i64 != want {
            // sanity: this is exactly the divergence PORT_SPEC trap 1 describes
            assert_eq!(raw.round() as i64, want + 1);
        }
    }
    // No other product has an exact-half case in that window (checked in the
    // generator); the sweep test above covers them anyway.
}
